<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted,nextTick} from 'vue';import axios from 'axios';import {useRoute,RouterLink} from 'vue-router';
const stream=ref<HTMLElement|null>(null),selfId=ref(0);
const route=useRoute(),chats=ref<any[]>([]),messages=ref<any[]>([]),content=ref(''),error=ref(''),busy=ref(false),loading=ref(false);let timer:ReturnType<typeof setInterval>|undefined,sequence=0;
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function refresh(){try{chats.value=(await axios.get('/api/chats')).data;}catch{error.value='消息列表加载失败';}}
async function poll(){if(!route.params.id||loading.value)return;const id=String(route.params.id),s=sequence;loading.value=true;try{if(!selfId.value)selfId.value=(await axios.get('/api/people/me')).data.id;const {data}=await axios.get('/api/chats/'+id+'/messages',{params:{after:messages.value.at(-1)?.id||0}});if(s!==sequence)return;const atBottom=!stream.value||stream.value.scrollHeight-stream.value.scrollTop-stream.value.clientHeight<80;messages.value.push(...data);await nextTick();if(atBottom&&stream.value)stream.value.scrollTop=stream.value.scrollHeight;if(data.length){await axios.post('/api/chats/'+id+'/read',null,{params:{through:data.at(-1).id},headers:await headers()});window.dispatchEvent(new Event('notifications-updated'));await refresh();}}catch{if(s===sequence)error.value='消息加载失败或无权访问该对话';}finally{loading.value=false;}}
async function send(){busy.value=true;error.value='';try{await axios.post('/api/chats/'+route.params.id+'/messages',{content:content.value},{headers:await headers()});content.value='';await poll();}catch{error.value='发送失败，请重试';}finally{busy.value=false;}}
watch(()=>route.params.id,()=>{sequence++;messages.value=[];error.value='';loading.value=false;poll();},{immediate:true});onMounted(()=>{refresh();timer=setInterval(()=>{if(!document.hidden){poll();refresh();}},3000);});onUnmounted(()=>{if(timer)clearInterval(timer);sequence++;});
</script><template><section class="messages"><RouterLink to="/notifications">← 消息中心</RouterLink><h1>私聊</h1><p role="alert">{{error}}</p><div class="chat-layout"><main v-if="route.params.id"><header><RouterLink v-if="chats.find(c=>String(c.id)===String(route.params.id))" :to="'/people/'+chats.find(c=>String(c.id)===String(route.params.id)).peerId">{{chats.find(c=>String(c.id)===String(route.params.id)).peerName}} · 查看主页 ↗</RouterLink></header><div ref="stream" class="chat-stream"><article v-for="m in messages" :key="m.id" :class="{mine:m.senderId===selfId}"><RouterLink :to="'/people/'+m.senderId"><img :src="'/api/conversations/avatars/'+m.senderId" alt="发言者头像"></RouterLink><div><strong>{{m.username}}</strong><time>{{m.createdAt}}</time><p>{{m.content}}</p></div></article><p v-if="!messages.length">开始你们的校园对话。</p></div><form @submit.prevent="send"><textarea v-model="content" required maxlength="2000" placeholder="询问商品、约定线下交接…"></textarea><div><button v-for="emoji in ['😊','👍','🙏']" type="button" @click="content+=emoji">{{emoji}}</button><button :disabled="busy||!content.trim()">{{busy?'发送中…':'发送'}}</button></div></form></main><main v-else>选择一位同学开始聊天。</main></div></section></template><style scoped>.messages{flex:1;background:#f6f4ee;color:#293d3b;padding:30px 5%}h1{font-size:30px;margin:10px 0 25px}.chat-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:20px}aside,main{background:white;padding:20px;border-radius:12px;min-width:0}aside a{display:flex;gap:10px;align-items:center;color:#304b49;text-decoration:none;padding:15px 8px;border-bottom:1px solid #eee;font-size:13px}aside .active{background:#f6efd9}aside img,article img{width:35px;height:35px;border-radius:50%;object-fit:cover}b{background:#c34b43;color:white;font-size:10px;border-radius:12px;padding:3px 6px}header a{color:#94744c;font-size:13px}.chat-stream{max-height:52vh;overflow:auto;padding:12px 0}article{display:flex;gap:12px;margin:20px 0}article>div{max-width:78%;background:#f5f3eb;border-radius:0 10px 10px;padding:15px;min-width:0}strong{font-size:12px}time{font-size:10px;color:#8c927d;margin-left:15px}article p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8}textarea{width:100%;min-height:80px;border:1px solid #dde0d4;border-radius:6px;font:inherit;padding:12px}button{background:#304b49;color:white;border:0;border-radius:4px;padding:9px 15px;margin:10px 8px 0 0;cursor:pointer}button:disabled{opacity:.5}@media(max-width:700px){.chat-layout{grid-template-columns:1fr}aside{max-height:180px;overflow:auto}}article.mine{flex-direction:row-reverse}article.mine>div{background:#e5eddc;border-radius:10px 0 10px 10px}.mine strong{color:#365448}article>div p{margin-bottom:0}@media(max-width:500px){article>div{max-width:82%}time{display:block;margin:5px 0 0}}</style>
